import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new IOException("Unexpected character: " + (char) c);
                }
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int maxEdges = 2 * m;
        int maxS = 2 * n;

        int[] head = new int[maxS + 1];
        Arrays.fill(head, -1);

        int[] toU = new int[maxEdges];
        int[] toV = new int[maxEdges];
        int[] nxt = new int[maxEdges];
        int[] dpVal = new int[maxEdges];
        int edgeCount = 0;

        int[] deg = new int[n + 1];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();

            deg[u]++;
            deg[v]++;

            int s = u + v;

            toU[edgeCount] = u;
            toV[edgeCount] = v;
            nxt[edgeCount] = head[s];
            head[s] = edgeCount++;

            toU[edgeCount] = v;
            toV[edgeCount] = u;
            nxt[edgeCount] = head[s];
            head[s] = edgeCount++;
        }

        int[] maxDp = new int[n + 1];
        Arrays.fill(maxDp, -1);

        for (int s = maxS; s >= 2; s--) {
            int e = head[s];
            if (e == -1) continue;

            int curr = e;
            while (curr != -1) {
                int v = toV[curr];
                dpVal[curr] = (maxDp[v] == -1) ? 0 : maxDp[v] + 1;
                curr = nxt[curr];
            }

            curr = e;
            while (curr != -1) {
                int u = toU[curr];
                if (dpVal[curr] > maxDp[u]) {
                    maxDp[u] = dpVal[curr];
                }
                curr = nxt[curr];
            }
        }

        PrintWriter out = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();

        for (int i = 1; i <= n; i++) {
            int ans;
            if (deg[i] == 0) {
                ans = 1;
            } else {
                ans = 2 + maxDp[i];
            }
            sb.append(ans).append(i == n ? "" : " ");
            if (sb.length() > 65536) {
                out.print(sb.toString());
                sb.setLength(0);
            }
        }

        if (sb.length() > 0) {
            out.print(sb.toString());
        }
        out.println();
        out.flush();
    }
}
